suppressPackageStartupMessages(library(edgeR));suppressPackageStartupMessages(library(limma))
B<-'/mnt/BioDisk/wangmingyuan/GI_preanalysis_20260923';V<-file.path(B,'GC_validation_v2');O<-file.path(V,'replacement_candidates');dir.create(O,recursive=TRUE,showWarnings=FALSE)
writeLines(c('Second alternative screen, preserving prior all-gene FDR and all negative sensitivities.', 'Before selecting final three, inspect epithelial and gastric differentiation proxies to address anatomical origin, particularly for down-regulated candidates.', 'Three full-genome models: epithelial, gastric markers, both. Genes from entire original universe; no candidate-only FDR.'),file.path(O,'EPITHELIAL_PLAN.txt'))
m<-read.delim(file.path(V,'04_results/FABP4_audit/sample_values.tsv'),check.names=FALSE);m$patient<-factor(m$patient);m$site<-factor(m$site,levels=c('GCPT','GCPM'));m$preservation<-factor(m$preservation)
lc<-read.delim(gzfile(file.path(B,'03_processed/GC314812_TMM_logCPM.tsv.gz')),check.names=FALSE);E<-as.matrix(lc[,m$sample]);sets<-list(epithelial=c('EPCAM','KRT8','KRT18','KRT19'),gastric=c('MUC5AC','MUC6','PGC','LIPF','GKN1','GKN2'))
cover<-data.frame()
for(g in names(sets)){measured<-sets[[g]][sets[[g]]%in%lc$symbol];stopifnot(length(measured)>=3);m[[g]]<-colMeans(E[lc$symbol%in%measured,,drop=FALSE]);cover<-rbind(cover,data.frame(proxy=g,measured=paste(measured,collapse=';'),missing=paste(setdiff(sets[[g]],measured),collapse=';')))}
write.table(cover,file.path(O,'proxy_coverage.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
x<-read.delim(gzfile(file.path(B,'02_raw/GSE314812_counts.tsv.gz')),check.names=FALSE);cnt<-as.matrix(x[,m$sample]);rownames(cnt)<-x$gene_id;orig<-read.delim(file.path(B,'04_results/GC_bulk/paired_preservation_adjusted_DE.tsv'),check.names=FALSE);d<-calcNormFactors(DGEList(cnt[match(orig$gene_id,rownames(cnt)),,drop=FALSE]));forms<-list(epithelial=~patient+preservation+epithelial+site,gastric=~patient+preservation+gastric+site,both=~patient+preservation+epithelial+gastric+site)
gs<-c('PSD4','DSEL','SLC45A4','PTPRQ','RAP1GAP2','OPLAH','IGSF10','THSD7A','KIAA1324L','CAPN15');out<-list()
for(k in names(forms)){de<-model.matrix(forms[[k]],m);stopifnot(qr(de)$rank==ncol(de));v<-voom(d,de,plot=FALSE);f<-eBayes(lmFit(v,de));tt<-topTable(f,coef='siteGCPM',number=Inf,sort.by='none',confint=TRUE);tt$gene_id<-rownames(tt);tt$symbol<-orig$symbol[match(tt$gene_id,orig$gene_id)];write.table(tt,gzfile(file.path(O,paste0(k,'_all_genes.tsv.gz'))),sep='\t',quote=FALSE,row.names=FALSE);out[[k]]<-data.frame(model=k,tt[tt$symbol%in%gs,])}
r<-do.call(rbind,out);write.table(r,file.path(O,'pool_epithelial_sensitivity.tsv'),sep='\t',quote=FALSE,row.names=FALSE);write.table(m,file.path(O,'proxy_sample_values.tsv'),sep='\t',quote=FALSE,row.names=FALSE);print(r[,c('model','symbol','logFC','P.Value','adj.P.Val')]);writeLines('exit_code=0; full_rank_models; 20827 genes',file.path(O,'EPITHELIAL_COMPLETE.txt'))
